  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Přehrada Ogosta', 'Druhé největší umělé jezero Bulharska u města Montana, dokončené po dvaceti letech stavby roku 1986. Silnice po koruně hráze nabízí široký výhled na hladinu i Balkán na obzoru.', 43.3718, 23.176, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ogosta-dam-near-Borovtsi.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ogosta-dam-near-Borovtsi.jpg"}'::text[], 1, '{}'::jsonb),
    (v_route, 'Jeskyně Ledenika', 'Krápníková jeskyně ve Vračanském Balkánu proslulá ledovými útvary v zimě a síní zvanou Velký chrám. Přístupová silnice od Vraci je sama o sobě vyhlídková jízda.', 43.20444, 23.49111, 'https://commons.wikimedia.org/wiki/Special:FilePath/Ledenika_cave_045.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Ledenika_cave_045.jpg"}'::text[], 2, '{}'::jsonb),
    (v_route, 'Berkovica', 'Podhorské městečko pod vrcholem Kom v západní Staré planině s nedalekým Klisurským klášterem. Příjemné náměstí s kašnami je poslední civilizace před horskými serpentinami.', 43.2361, 23.1258, 'https://commons.wikimedia.org/wiki/Special:FilePath/Berkovitsa-IVHM.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Berkovitsa-IVHM.jpg"}'::text[], 5, '{}'::jsonb),
    (v_route, 'Čiprovci', 'Městečko na řece Ogostě u srbské hranice, proslulé staletou tradicí ručního tkaní kilimů. Muzeum koberců a klidné uličky jsou nečekaná kulturní zastávka v horách.', 43.38417, 22.88083, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chiprovtsi-centre.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chiprovtsi-centre.jpg"}'::text[], 6, '{}'::jsonb);
