    (v_route, 'Synagoga v Třešti', 'Synagoga na území Třeště. Památka v Česku — kus historie přímo u trasy.', 49.2927, 15.4822, 'http://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99e%C5%A1%C5%A5%2C%20synagoga%20%2801%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/T%C5%99e%C5%A1%C5%A5%2C%20synagoga%20%2801%29.jpg"}'::text[], 8, '{"en": {"name": "Synagogue in Třešť", "description": "Synagogue in Třešť, Czech Republic. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Synagoge", "description": "Synagoge in Třešť, Tschechien. Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Synagoga v Třešti", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Synagoga v Třešti", "description": "Synagoge in Třešť, Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Synagoga v Třešti", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Synagoga v Třešti", "description": "Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Synagoga v Třešti", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb);
