-- ── Estonsko – Saaremaa a Lahemaa (+5 bodů) ───────────
do $$
declare v_route uuid;
begin
  select id into v_route from public.routes where name = 'Estonsko – Saaremaa a Lahemaa' limit 1;
  if v_route is null then raise notice 'Trasa nenalezena: Estonsko – Saaremaa a Lahemaa'; return; end if;
  delete from public.route_pois where route_id = v_route and name in ('Vodopád Jägala', 'Rašeliniště Viru (Lahemaa)', 'Rummu – zatopený lom', 'Haapsalu – biskupský hrad', 'Koguva – muzejní vesnice (Muhu)');
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Vodopád Jägala', 'Nejširší přírodní vodopád Estonska — asi 8 metrů vysoký a přes 50 metrů široký. V zimě vytváří ledovou stěnu s tunelem, po zbytek roku hřmící vodní oponu kousek od silnice.', 59.4511, 25.1833, 'https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%A4gala%20Juga%20(J%C3%A4galafallet).JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/J%C3%A4gala%20Juga%20(J%C3%A4galafallet).JPG"}'::text[], 2, '{}'::jsonb),
    (v_route, 'Rašeliniště Viru (Lahemaa)', 'Rašeliniště s 3,5 km povalovým chodníkem a vyhlídkovou věží, nejdostupnější bažina národního parku Lahemaa. Procházka mezi jezírky zabere hodinu a je to jiný svět.', 59.4685, 25.6545, 'https://commons.wikimedia.org/wiki/Special:FilePath/Viru-raba-lahemaa-nature-park.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Viru-raba-lahemaa-nature-park.jpg"}'::text[], 3, '{}'::jsonb),
    (v_route, 'Rummu – zatopený lom', 'Zatopený vápencový lom s částečně potopenými ruinami sovětské věznice Murru. Tyrkysová voda a bílá halda dělají z bývalého gulagu jedno z nejsurreálnějších míst Pobaltí.', 59.2264, 24.1902, 'https://commons.wikimedia.org/wiki/Special:FilePath/Rummu%20karj%C3%A4%C3%A4r.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Rummu%20karj%C3%A4%C3%A4r.JPG"}'::text[], 6, '{}'::jsonb),
    (v_route, 'Haapsalu – biskupský hrad', 'Biskupský hrad s katedrálou ze 13. století v lázeňském městečku na pobřeží. Podle legendy se při srpnovém úplňku na okně kaple zjevuje Bílá paní.', 58.9472, 23.5386, 'https://commons.wikimedia.org/wiki/Special:FilePath/Haapsalu%20linnus.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Haapsalu%20linnus.jpg"}'::text[], 7, '{}'::jsonb),
    (v_route, 'Koguva – muzejní vesnice (Muhu)', 'Nejzachovalejší tradiční vesnice Estonska s kamennými zídkami a doškovými střechami na ostrově Muhu. Funguje jako muzeum v přírodě a je rodištěm spisovatele Juhana Smuula.', 58.5956, 23.0806, 'https://commons.wikimedia.org/wiki/Special:FilePath/Koguva%20k%C3%BClavahe.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Koguva%20k%C3%BClavahe.jpg"}'::text[], 9, '{}'::jsonb);
  update public.route_pois set sort_order = 4, updated_at = now() where route_id = v_route and name = 'Palmse mõis (Lahemaa)';
  update public.route_pois set sort_order = 5, updated_at = now() where route_id = v_route and name = 'Sagadi mõis (Lahemaa)';
  update public.route_pois set sort_order = 8, updated_at = now() where route_id = v_route and name = 'Trajekt Virtsu–Kuivastu';
  update public.route_pois set sort_order = 10, updated_at = now() where route_id = v_route and name = 'Angla – větrné mlýny';
  update public.route_pois set sort_order = 11, updated_at = now() where route_id = v_route and name = 'Panga pank – útes';
  update public.route_pois set sort_order = 12, updated_at = now() where route_id = v_route and name = 'Kaali – meteoritický kráter';
  update public.route_pois set sort_order = 13, updated_at = now() where route_id = v_route and name = 'Restaurace: MO Restaurant (Kuressaare)';
  update public.route_pois set sort_order = 14, updated_at = now() where route_id = v_route and name = 'Kuressaare – biskupský hrad';
  update public.route_pois set sort_order = 15, updated_at = now() where route_id = v_route and name = 'Sõrve – maják';
  update public.routes set waypoints = '[{"lat": 59.4358, "lng": 24.7405, "label": "Tallinn – staré město (start)"}, {"lat": 59.4511, "lng": 25.1833, "label": "Vodopád Jägala"}, {"lat": 59.4685, "lng": 25.6545, "label": "Rašeliniště Viru (Lahemaa)"}, {"lat": 59.51275, "lng": 25.95477, "label": "Palmse mõis (Lahemaa)"}, {"lat": 59.5167, "lng": 26.118, "label": "Sagadi mõis (Lahemaa)"}, {"lat": 59.2264, "lng": 24.1902, "label": "Rummu – zatopený lom"}, {"lat": 58.9472, "lng": 23.5386, "label": "Haapsalu – biskupský hrad"}, {"lat": 58.575, "lng": 23.51, "label": "Trajekt Virtsu–Kuivastu"}, {"lat": 58.5737, "lng": 23.39655, "label": "Přístav Kuivastu (Muhu) – výstup"}, {"lat": 58.5956, "lng": 23.0806, "label": "Koguva – muzejní vesnice (Muhu)"}, {"lat": 58.549, "lng": 22.632, "label": "Angla – větrné mlýny"}, {"lat": 58.56986, "lng": 22.29038, "label": "Panga pank – útes"}, {"lat": 58.37279, "lng": 22.6694, "label": "Kaali – meteoritický kráter"}, {"lat": 58.2589, "lng": 22.5119, "label": "Restaurace: MO Restaurant (Kuressaare)"}, {"lat": 58.25382, "lng": 22.49217, "label": "Kuressaare – biskupský hrad"}, {"lat": 57.90982, "lng": 22.05537, "label": "Sõrve – maják (cíl)"}]'::jsonb, mapy_url = 'https://www.google.com/maps/dir/?api=1&origin=59.4358,24.7405&destination=57.90982,22.05537&travelmode=driving&waypoints=59.4511,25.1833%7C59.4685,25.6545%7C59.51275,25.95477%7C59.5167,26.118%7C59.2264,24.1902%7C58.9472,23.5386%7C58.575,23.51%7C58.5737,23.39655%7C58.5956,23.0806%7C58.549,22.632%7C58.56986,22.29038%7C58.37279,22.6694%7C58.2589,22.5119%7C58.25382,22.49217', geometry = null, updated_at = now() where id = v_route;
