    (v_route, 'Lake Paatari', 'Vodní plocha ve Finsku — příjemný cíl vyjížďky s výhledy na hladinu.', 68.86503, 26.5695, null, '{}'::text[], 10, '{"en": {"name": "Lake Paatari", "description": "Lake in Inari, Finland. A body of water in Finland — a pleasant ride destination with waterside views."}, "de": {"name": "Paatari", "description": "See in der finnischen Gemeinde Inari. Ein Gewässer in Finnland — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Lake Paatari", "description": "Akwen w Finlandii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Lake Paatari", "description": "Meer in Finland. Een waterpartij in Finland — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Lake Paatari", "description": "Una masa de agua en Finlandia: un destino agradable con vistas al agua."}, "fr": {"name": "Paatari", "description": "Lac à Inari, en Finlande. Un plan d''eau en Finlande — une belle destination avec vue sur l''eau."}, "uk": {"name": "Lake Paatari", "description": "Водойма у Фінляндії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
