    (v_route, 'Rijeka Cathedral', 'Památka v Chorvatsku — kus historie přímo u trasy.', 45.32779, 14.44444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Crkva%20Sv%20Vida%20Rijeka%20140807.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Crkva%20Sv%20Vida%20Rijeka%20140807.jpg"}'::text[], 1, '{"en": {"name": "Rijeka Cathedral", "description": "Roman Catholic cathedral in Rijeka, Croatia. A heritage sight in Croatia — a piece of history right on your route."}, "de": {"name": "St. Vitus", "description": "Kathedrale in Rijeka, Kroatien. Ein Denkmal in Kroatien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Katedra Świętego Wita w Rijece", "description": "Świątynia katolicka. Zabytek w Chorwacji — kawałek historii tuż przy trasie."}, "nl": {"name": "Rijeka Cathedral", "description": "Kathedraal van bisdom Roman Catholic Archdiocese of Rijeka, Kroatië. Een monument in Kroatië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Catedral de San Vito", "description": "Un monumento en Croacia: un pedazo de historia junto a la ruta."}, "fr": {"name": "cathédrale Saint-Guy de Rijeka", "description": "Un monument en Croatie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Собор Святого Віта", "description": "Кафедральний собор в Рієці, Хорватія. Пам''ятка у Хорватії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'jeskyně Biserujka', 'Krasová jeskyně na ostrove Krk v Chorvatsku. Přírodní zajímavost v Chorvatsku — místo na protažení nohou uprostřed přírody.', 45.18731, 14.60978, 'http://commons.wikimedia.org/wiki/Special:FilePath/Biserujka%20H%C3%B6hle%202007%20Kroatien%20112.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Biserujka%20H%C3%B6hle%202007%20Kroatien%20112.jpg"}'::text[], 2, '{"en": {"name": "Biserujka cave", "description": "Karst cave on island Krk in Croatia. A natural sight in Croatia — a spot to stretch your legs amid nature."}, "de": {"name": "Biserujka Höhle", "description": "Höhle in Kroatien. Eine Natursehenswürdigkeit in Kroatien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "jeskyně Biserujka", "description": "Atrakcja przyrodnicza w Chorwacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Biserujka", "description": "Een natuurbezienswaardigheid in Kroatië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Cueva de Biserujka", "description": "Un paraje natural en Croacia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Biserujka", "description": "Un site naturel en Croatie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "jeskyně Biserujka", "description": "Природна пам''ятка у Хорватії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Národní park Severní Velebit', 'Národní park v Chorvatsku. Přírodní zajímavost v Chorvatsku — místo na protažení nohou uprostřed přírody.', 44.76221, 14.9741, 'http://commons.wikimedia.org/wiki/Special:FilePath/Karstformationen%20Nationalpark-Nord-Velebit.JPG', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Karstformationen%20Nationalpark-Nord-Velebit.JPG"}'::text[], 4, '{"en": {"name": "Northern Velebit National Park", "description": "National park in Croatia. A natural sight in Croatia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Nördlicher Velebit", "description": "Nationalpark in Kroatien. Eine Natursehenswürdigkeit in Kroatien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Welebitu Północnego", "description": "Atrakcja przyrodnicza w Chorwacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "National Park Sjeverni Velebit", "description": "Een natuurbezienswaardigheid in Kroatië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Parque nacional Sjeverni Velebit", "description": "Área protegida de Croacia. Un paraje natural en Croacia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Sjeverni Velebit", "description": "Parc national de Croatie. Un site naturel en Croatie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Північний Велебит", "description": "Природна пам''ятка у Хорватії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Paklenica', 'Krasový říční kaňon a národní park v Chorvatsku. Přírodní zajímavost v Chorvatsku — místo na protažení nohou uprostřed přírody.', 44.44359, 15.29022, 'http://commons.wikimedia.org/wiki/Special:FilePath/Paklenica.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Paklenica.jpg"}'::text[], 7, '{"en": {"name": "Paklenica", "description": "National park in Croatia. A natural sight in Croatia — a spot to stretch your legs amid nature."}, "de": {"name": "Nationalpark Paklenica", "description": "Nationalpark in Kroatien. Eine Natursehenswürdigkeit in Kroatien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Park Narodowy Paklenica", "description": "Atrakcja przyrodnicza w Chorwacji — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Paklenica", "description": "Park in Kroatië. Een natuurbezienswaardigheid in Kroatië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Paklenica", "description": "Área protegida de Croacia. Un paraje natural en Croacia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "parc national de Paklenica", "description": "Parc national de Croatie. Un site naturel en Croatie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Паклениця", "description": "Природоохоронна територія. Природна пам''ятка у Хорватії — місце розім''яти ноги серед природи."}}'::jsonb);
