    (v_route, 'V Klučí', 'Přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.3131, 15.5236, null, '{}'::text[], 0, '{"en": {"name": "V Klučí", "description": "Hill in Vílanec, Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "V Klučí", "description": "Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "V Klučí", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "V Klučí", "description": "Natuurgebied in Tsjechië. Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "V Klučí", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "V Klučí", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "V Klučí", "description": "Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
