    (v_route, 'Hošťanka', 'Přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.1655, 15.8718, 'http://commons.wikimedia.org/wiki/Special:FilePath/Trebic%20slavice%20hostanka%20stromy.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Trebic%20slavice%20hostanka%20stromy.jpg"}'::text[], 7, '{"en": {"name": "Hošťanka", "description": "Protected area in Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Hošťanka", "description": "Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Hošťanka", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Hošťanka", "description": "Natuurgebied in Tsjechië. Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Hošťanka", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Hošťanka", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Hošťanka", "description": "Природоохоронна територія в Чехії. Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Roštejn', 'Hrad v Česku. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.25167, 15.42639, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Ro%C5%A1tejn%20v%C4%9B%C5%BE%201.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hrad%20Ro%C5%A1tejn%20v%C4%9B%C5%BE%201.jpg"}'::text[], 8, '{"en": {"name": "Roštejn", "description": "Castle in the Czech republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Burg Roštejn", "description": "Burg in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Roštejn", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Burg Roštejn", "description": "Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Roštejn", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Roštejn", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Roštejn", "description": "Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb);
