    (v_route, 'Abbaye de Graville', 'Památka ve Francii — kus historie přímo u trasy.', 49.50349, 0.16492, 'http://commons.wikimedia.org/wiki/Special:FilePath/Graville1.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Graville1.jpg"}'::text[], 2, '{"en": {"name": "Abbaye de Graville", "description": "Abbey located in Seine-Maritime, in France. A heritage sight in France — a piece of history right on your route."}, "de": {"name": "Abtei Graville", "description": "Kloster in Frankreich. Ein Denkmal in Frankreich — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Abbaye de Graville", "description": "Zabytek we Francji — kawałek historii tuż przy trasie."}, "nl": {"name": "Abtei Graville", "description": "Een monument in Frankrijk — een stuk geschiedenis vlak aan de route."}, "es": {"name": "abadía de Graville", "description": "Abadía situada en Sena Marítimo, en Francia. Un monumento en Francia: un pedazo de historia junto a la ruta."}, "fr": {"name": "abbaye de Graville", "description": "Abbaye située en Seine-Maritime, en France. Un monument en France — un morceau d''histoire au bord de la route."}, "uk": {"name": "Abbaye de Graville", "description": "Пам''ятка у Франції — шматочок історії просто на маршруті."}}'::jsonb);
