    (v_route, 'Chvojnov', 'Přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.4062, 15.418, 'http://commons.wikimedia.org/wiki/Special:FilePath/Chvojnov%202.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Chvojnov%202.jpg"}'::text[], 0, '{"en": {"name": "Chvojnov", "description": "Protected area in Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Chvojnov", "description": "Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Chvojnov", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Chvojnov", "description": "Natuurgebied in Tsjechië. Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Chvojnov", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Chvojnov", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Chvojnov", "description": "Природоохоронна територія в Чехії. Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb);
