  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Ormožské jezero', 'Přehradní nádrž nacházející se na hranici Chorvatska a Slovinska. Vodní plocha ve Slovinsku — příjemný cíl vyjížďky s výhledy na hladinu.', 46.39056, 16.17278, 'http://commons.wikimedia.org/wiki/Special:FilePath/ISS023-E-18089%20-%20View%20of%20Croatia.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/ISS023-E-18089%20-%20View%20of%20Croatia.jpg"}'::text[], 1, '{"en": {"name": "Lake Ormož", "description": "Reservoir on the river Drava, border between Croatia and Slovenia. A body of water in Slovenia — a pleasant ride destination with waterside views."}, "de": {"name": "Stausee Ormož", "description": "Stausee der Drau an der Grenze zwischen Slowenien und Kroatien. Ein Gewässer in Slowenien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Ormožské jezero", "description": "Akwen w Słowenii — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Ormožské jezero", "description": "Stuwmeer in Ormož, Kroatië. Een waterpartij in Slovenië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Ormožské jezero", "description": "Una masa de agua en Eslovenia: un destino agradable con vistas al agua."}, "fr": {"name": "Ormožské jezero", "description": "Un plan d''eau en Slovénie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Ormožské jezero", "description": "Водойма у Словенії — приємна мета поїздки з краєвидами на воду."}}'::jsonb);
