    (v_route, 'Prameny Vevčani', 'Krasové prameny vyvěrající z jeskyně na svahu pohoří Jablanica s vydatností až 4000 litrů za sekundu. Dřevěné lávky nad ledovou vodou a vyhlášená vesnická kuchyně.', 41.2394, 20.5853, null, '{}'::text[], 3, '{}'::jsonb),
    (v_route, 'Kruševo – Makedonium', 'Futuristický betonový památník Ilindenského povstání z roku 1974 na kopci nad nejvýše položeným městem Balkánu. Serpentiny do Kruševa jsou motorkářská lahůdka samy o sobě.', 41.3774, 21.2484, 'https://commons.wikimedia.org/wiki/Special:FilePath/Makedonium_09.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Makedonium_09.JPG"}'::text[], 7, '{}'::jsonb),
    (v_route, 'Heraclea Lyncestis', 'Antické město založené Filipem II. Makedonským ve 4. století př. n. l. kousek za Bitolou. Římské divadlo a raně byzantské podlahové mozaiky patří k nejlepším v zemi.', 41.0111, 21.3425, 'https://commons.wikimedia.org/wiki/Special:FilePath/Heraclea_Lyncestis.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Heraclea_Lyncestis.jpg"}'::text[], 10, '{}'::jsonb),
    (v_route, 'Zátoka kostí – muzeum na vodě', 'Rekonstrukce prehistorické kůlové osady z doby bronzové na hladině Ochridského jezera u Peštani. Na dně bylo nalezeno přes 6000 dřevěných kůlů původní osady.', 40.9946, 20.798, 'https://commons.wikimedia.org/wiki/Special:FilePath/The_Museum_%22Bay_of_the_Bones%22_on_the_Lake_Ohrid,_Macedonia.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/The_Museum_%22Bay_of_the_Bones%22_on_the_Lake_Ohrid,_Macedonia.jpg"}'::text[], 12, '{}'::jsonb);
