-- ── Sozopol a jižní Černomoří (+5 bodů) ───────────────
do $$
declare v_route uuid;
begin
  select id into v_route from public.routes where name = 'Sozopol a jižní Černomoří' limit 1;
  if v_route is null then raise notice 'Trasa nenalezena: Sozopol a jižní Černomoří'; return; end if;
  delete from public.route_pois where route_id = v_route and name in ('Carevo', 'Beglik Tash – thrácká svatyně', 'Pomorie – solné jezero a Muzeum soli', 'Přímořská zahrada Burgas', 'Černomorec');
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Carevo', 'Pobřežní městečko a jeden ze vstupních přístavů jižního Černomoří. Přístavní promenáda a kostelík nad mořem jsou příjemná zastávka na kávu při jízdě podél pobřeží.', 42.1667, 27.85, 'https://commons.wikimedia.org/wiki/Special:FilePath/Tsarevo-Vasiliko-Church_06-Lazarov-IFB.JPG', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Tsarevo-Vasiliko-Church_06-Lazarov-IFB.JPG"}'::text[], 2, '{}'::jsonb),
    (v_route, 'Beglik Tash – thrácká svatyně', 'Megalitická skalní svatyně z doby železné na mysu severně od Primorska, objevená až roku 2002. Obří kameny sluneční observatoře stojí pár minut od silnice a nabízí výhled na moře.', 42.307, 27.7667, 'https://commons.wikimedia.org/wiki/Special:FilePath/Beglik_Tash_014.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Beglik_Tash_014.jpg"}'::text[], 4, '{}'::jsonb),
    (v_route, 'Pomorie – solné jezero a Muzeum soli', 'Ultraslaná laguna se staletou tradicí těžby mořské soli a jediným muzeem soli ve východní Evropě. V zimě tu zimují tisíce plameňáků, solné pánve lemují silnici na Nesebar.', 42.5586, 27.6439, 'https://commons.wikimedia.org/wiki/Special:FilePath/Lake_Pomorie_2010.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Lake_Pomorie_2010.jpg"}'::text[], 7, '{}'::jsonb),
    (v_route, 'Přímořská zahrada Burgas', 'Největší park Burgasu založený roku 1910 se táhne podél pláže v centru města. Ideální místo na protažení nohou a zmrzlinu v půlce cesty mezi Ropotamem a Nesebarem.', 42.49861, 27.48167, 'https://commons.wikimedia.org/wiki/Special:FilePath/Sea_Garden-Burgas_(3).jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Sea_Garden-Burgas_(3).jpg"}'::text[], 8, '{}'::jsonb),
    (v_route, 'Černomorec', 'Malé pobřežní letovisko se zátokami a plážemi kousek před Sozopolem. Klidnější alternativa rušných letovisek — poslední zastávka okruhu s výhledem na Burgaský záliv.', 42.44408, 27.63902, 'https://commons.wikimedia.org/wiki/Special:FilePath/Chernomorets-3.jpg', '{"https://commons.wikimedia.org/wiki/Special:FilePath/Chernomorets-3.jpg"}'::text[], 9, '{}'::jsonb);
  update public.route_pois set sort_order = 1, updated_at = now() where route_id = v_route and name = 'Pláž Djuni';
  update public.route_pois set sort_order = 3, updated_at = now() where route_id = v_route and name = 'Ahtopol';
  update public.route_pois set sort_order = 5, updated_at = now() where route_id = v_route and name = 'Rezervace Ropotamo';
  update public.route_pois set sort_order = 6, updated_at = now() where route_id = v_route and name = 'Nesebar';
  update public.routes set waypoints = '[{"lat": 42.4181, "lng": 27.6953, "label": "Start: Sozopol"}, {"lat": 42.32, "lng": 27.72, "label": "Ropotamo"}, {"lat": 42.268, "lng": 27.75, "label": "Pláž Djuni"}, {"lat": 42.1667, "lng": 27.85, "label": "Carevo"}, {"lat": 42.09939, "lng": 27.94071, "label": "Ahtopol"}, {"lat": 42.307, "lng": 27.7667, "label": "Beglik Tash – thrácká svatyně"}, {"lat": 42.3275, "lng": 27.75556, "label": "Rezervace Ropotamo"}, {"lat": 42.65871, "lng": 27.73627, "label": "Nesebar"}, {"lat": 42.5586, "lng": 27.6439, "label": "Pomorie – solné jezero a Muzeum soli"}, {"lat": 42.49861, "lng": 27.48167, "label": "Přímořská zahrada Burgas"}, {"lat": 42.44408, "lng": 27.63902, "label": "Černomorec"}, {"lat": 42.4181, "lng": 27.6953, "label": "Cíl: Sozopol"}]'::jsonb, mapy_url = 'https://www.google.com/maps/dir/?api=1&origin=42.4181,27.6953&destination=42.4181,27.6953&travelmode=driving&waypoints=42.32,27.72%7C42.268,27.75%7C42.1667,27.85%7C42.09939,27.94071%7C42.307,27.7667%7C42.3275,27.75556%7C42.65871,27.73627%7C42.5586,27.6439%7C42.49861,27.48167%7C42.44408,27.63902', geometry = null, updated_at = now() where id = v_route;
end $$;

