-- ── UNESCO trojúhelník – Telč, Třebíč, Zelená hora (+2 bodů) ─
do $$
declare v_route uuid;
begin
  select id into v_route from public.routes where name = 'UNESCO trojúhelník – Telč, Třebíč, Zelená hora' limit 1;
  if v_route is null then raise notice 'Trasa nenalezena: UNESCO trojúhelník – Telč, Třebíč, Zelená hora'; return; end if;
  delete from public.route_pois where route_id = v_route and name in ('Nová Říše', 'Baba – V Bukách');
  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Nová Říše', 'Klášter. Památka v Česku — kus historie přímo u trasy.', 49.13943, 15.56488, 'http://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A1%20%C5%98%C3%AD%C5%A1e%20Monastery%2003.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Nov%C3%A1%20%C5%98%C3%AD%C5%A1e%20Monastery%2003.jpg"}'::text[], 1, '{"en": {"name": "Nová Říše", "description": "Abbey. A heritage sight in Czechia — a piece of history right on your route."}, "de": {"name": "Abtei Nová Říše", "description": "Ein Denkmal in Tschechien — ein Stück Geschichte direkt an der Route."}, "pl": {"name": "Nová Říše", "description": "Zabytek w Czechach — kawałek historii tuż przy trasie."}, "nl": {"name": "Nová Říše", "description": "Abdij in Tsjechië. Een monument in Tsjechië — een stuk geschiedenis vlak aan de route."}, "es": {"name": "Nová Říše", "description": "Un monumento en Chequia: un pedazo de historia junto a la ruta."}, "fr": {"name": "Nová Říše", "description": "Abbaye tchèque. Un monument en Tchéquie — un morceau d''histoire au bord de la route."}, "uk": {"name": "Nová Říše", "description": "Пам''ятка в Чехії — шматочок історії просто на маршруті."}}'::jsonb),
    (v_route, 'Baba – V Bukách', 'Přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.4563, 15.8653, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sk%C3%A1la%20Baba.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sk%C3%A1la%20Baba.jpg"}'::text[], 6, '{"en": {"name": "Baba – V bukách", "description": "Protected area in Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Baba – V Bukách", "description": "Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Baba – V Bukách", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Baba – V Bukách", "description": "Natuurgebied in Tsjechië. Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Baba - V Bukách", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Baba – V Bukách", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Baba – V Bukách", "description": "Природоохоронна територія в Чехії. Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb);
