    (v_route, 'Vodní nádrž Sedlice', 'Přehradní nádrž vybudovaná v letech 1921–1927 na řece Želivce pod soutokem říčky Hejlovky a Jankovského potoka, zhruba 7 km jihozápadně od Humpolce. Její hráz je od roku 2012 kulturní památkou České republiky. Vodní plocha v Česku — příjemný cíl vyjížďky s výhledy na hladinu.', 49.51389, 15.26944, 'http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Sedlice.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Vodn%C3%AD%20n%C3%A1dr%C5%BE%20Sedlice.jpg"}'::text[], 0, '{"en": {"name": "Sedlice Reservoir", "description": "Lake in Czech Republic. A body of water in Czechia — a pleasant ride destination with waterside views."}, "de": {"name": "Talsperre Sedlice", "description": "Stausee in Tschechien. Ein Gewässer in Tschechien — ein schönes Ausflugsziel mit Blick aufs Wasser."}, "pl": {"name": "Vodní nádrž Sedlice", "description": "Akwen w Czechach — przyjemny cel wycieczki z widokiem na wodę."}, "nl": {"name": "Vodní nádrž Sedlice", "description": "Meer in Tsjechië. Een waterpartij in Tsjechië — een fijn ritdoel met uitzicht over het water."}, "es": {"name": "Vodní nádrž Sedlice", "description": "Una masa de agua en Chequia: un destino agradable con vistas al agua."}, "fr": {"name": "Vodní nádrž Sedlice", "description": "Un plan d''eau en Tchéquie — une belle destination avec vue sur l''eau."}, "uk": {"name": "Vodní nádrž Sedlice", "description": "Водойма в Чехії — приємна мета поїздки з краєвидами на воду."}}'::jsonb),
    (v_route, 'zámek Herálec', 'Zámek v Herálci v okrese Havlíčkův Brod. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.53056, 15.45444, 'http://commons.wikimedia.org/wiki/Special:FilePath/Her%C3%A1lec%20z%C3%A1mek%204.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Her%C3%A1lec%20z%C3%A1mek%204.jpg"}'::text[], 7, '{"en": {"name": "zámek Herálec", "description": "A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "zámek Herálec", "description": "Schloss in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Zamek Herálec", "description": "Dawny zamek w Herálcu w kraju Wysoczyna (Czechy), obecnie pięciogwiazdkowy hotel Chateau Herálec. Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "zámek Herálec", "description": "Kasteel in Herálec, Tsjechië. Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "zámek Herálec", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "zámek Herálec", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "zámek Herálec", "description": "Замок у Чехії. Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb);
