    (v_route, 'Hrad Eketorp', 'Hradiště ve Švédsku. Hrad či zámek ve Švédsku — historická zastávka, která stojí za odbočku.', 56.29556, 16.48611, 'http://commons.wikimedia.org/wiki/Special:FilePath/Eketorp%20main%20view.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Eketorp%20main%20view.jpg"}'::text[], 9, '{"en": {"name": "Eketorp Fort", "description": "Was built in the Iron Age around 400 AD. A castle in Sweden — a historic stop worth the detour."}, "de": {"name": "Burg Eketorp", "description": "Wurde in der Eisenzeit um 400 n. Chr. erbaut. Eine Burg bzw. ein Schloss in Schweden — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Eketorp Fort", "description": "Został zbudowany w epoce żelaza około 400 ne. Zamek w Szwecji — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Eketorp bolwerk", "description": "Werd gebouwd door de oude bevolking van de ijzertijd rond 400 na Christus als ringbolwerk - in een periode dat ze nauwe banden hadden met het Romeinse Rijk. Een kasteel in Zweden — een historische stop die de omweg waard is."}, "es": {"name": "Fuerte Eketorp", "description": "Fue construido en la Edad del Hierro alrededor del año 400 DC. Un castillo en Suecia: una parada histórica que merece el desvío."}, "fr": {"name": "forteresse d''Eketorp", "description": "A été construit à l''âge du fer environ 400 après JC. Un château en Suède — une halte historique qui vaut le détour."}, "uk": {"name": "Hrad Eketorp", "description": "Замок у Швеції — історична зупинка, варта об''їзду."}}'::jsonb);
  update public.route_pois set sort_order = 2, updated_at = now() where route_id = v_route and name = 'Zřícenina Borgholm';
  update public.route_pois set sort_order = 3, updated_at = now() where route_id = v_route and name = 'Restaurace: Hotell Borgholm (Borgholm)';
