  insert into public.route_pois (route_id, name, description, lat, lng, image_url, images, sort_order, translations) values
    (v_route, 'Čermákovy louky', 'Přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.3854, 15.3286, 'http://commons.wikimedia.org/wiki/Special:FilePath/PR%20%C4%8Cerm%C3%A1kovy%20louky%20%28stav%20kv%C4%9Bten%202023%29%20%2810%29.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/PR%20%C4%8Cerm%C3%A1kovy%20louky%20%28stav%20kv%C4%9Bten%202023%29%20%2810%29.jpg"}'::text[], 0, '{"en": {"name": "Čermákovy louky", "description": "Protected area in Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Čermákovy louky", "description": "Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Čermákovy louky", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Čermákovy louky", "description": "Natuurgebied in Tsjechië. Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Čermákovy louky", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Čermákovy louky", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Čermákovy louky", "description": "Природоохоронна територія в Чехії. Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Žďár nad Sázavou', 'Klášter a zámek ve Žďáru nad Sázavou. Hrad či zámek v Česku — historická zastávka, která stojí za odbočku.', 49.58306, 15.93722, 'http://commons.wikimedia.org/wiki/Special:FilePath/V%C4%9B%C5%BE%20u%20z%C3%A1mku%20ve%20%C5%BD%C4%8F%C3%A1ru%20nad%20S%C3%A1zavou.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/V%C4%9B%C5%BE%20u%20z%C3%A1mku%20ve%20%C5%BD%C4%8F%C3%A1ru%20nad%20S%C3%A1zavou.jpg"}'::text[], 1, '{"en": {"name": "Žďár monastery", "description": "Monastery in the Czech Republic. A castle in Czechia — a historic stop worth the detour."}, "de": {"name": "Kloster Žďár", "description": "Schloss in Tschechien. Eine Burg bzw. ein Schloss in Tschechien — ein historischer Halt, der den Umweg lohnt."}, "pl": {"name": "Žďár nad Sázavou", "description": "Zamek w Czechach — historyczny przystanek wart zjazdu z trasy."}, "nl": {"name": "Klooster Žďár nad Sázavou", "description": "Een kasteel in Tsjechië — een historische stop die de omweg waard is."}, "es": {"name": "Žďár nad Sázavou", "description": "Un castillo en Chequia: una parada histórica que merece el desvío."}, "fr": {"name": "Žďár nad Sázavou", "description": "Un château en Tchéquie — une halte historique qui vaut le détour."}, "uk": {"name": "Žďár nad Sázavou", "description": "Замок у Чехії. Замок у Чехії — історична зупинка, варта об''їзду."}}'::jsonb),
    (v_route, 'Baba – V Bukách', 'Přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.4563, 15.8653, 'http://commons.wikimedia.org/wiki/Special:FilePath/Sk%C3%A1la%20Baba.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Sk%C3%A1la%20Baba.jpg"}'::text[], 8, '{"en": {"name": "Baba – V bukách", "description": "Protected area in Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Baba – V Bukách", "description": "Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Baba – V Bukách", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Baba – V Bukách", "description": "Natuurgebied in Tsjechië. Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Baba - V Bukách", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Baba – V Bukách", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Baba – V Bukách", "description": "Природоохоронна територія в Чехії. Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb),
    (v_route, 'Zaječí skok', 'Přírodní rezervace v Česku. Přírodní zajímavost v Česku — místo na protažení nohou uprostřed přírody.', 49.4131, 15.535, 'http://commons.wikimedia.org/wiki/Special:FilePath/Hlavn%C3%AD%20vyhl%C3%ADdka%2C%20otisk%20podkovy%20kon%C4%9B.jpg', '{"http://commons.wikimedia.org/wiki/Special:FilePath/Hlavn%C3%AD%20vyhl%C3%ADdka%2C%20otisk%20podkovy%20kon%C4%9B.jpg"}'::text[], 9, '{"en": {"name": "Zaječí skok", "description": "Protected area in Czech Republic. A natural sight in Czechia — a spot to stretch your legs amid nature."}, "de": {"name": "Zaječí skok", "description": "Eine Natursehenswürdigkeit in Tschechien — ein Ort zum Beinevertreten mitten in der Natur."}, "pl": {"name": "Zaječí skok", "description": "Atrakcja przyrodnicza w Czechach — miejsce na rozprostowanie nóg pośród natury."}, "nl": {"name": "Zaječí skok", "description": "Natuurgebied in Tsjechië. Een natuurbezienswaardigheid in Tsjechië — een plek om de benen te strekken in de natuur."}, "es": {"name": "Zaječí skok", "description": "Área protegida de República Checa. Un paraje natural en Chequia: un lugar para estirar las piernas en plena naturaleza."}, "fr": {"name": "Zaječí skok", "description": "Un site naturel en Tchéquie — un endroit où se dégourdir les jambes en pleine nature."}, "uk": {"name": "Zaječí skok", "description": "Природоохоронна територія в Чехії. Природна пам''ятка в Чехії — місце розім''яти ноги серед природи."}}'::jsonb);
  update public.route_pois set sort_order = 2, updated_at = now() where route_id = v_route and name = 'Skalní útvar Devět skal';
  update public.route_pois set sort_order = 3, updated_at = now() where route_id = v_route and name = 'Skalní útvar Drátník';
