  update public.routes set waypoints = '[{"lat": 49.3464, "lng": 15.2119, "label": "Start – Mezná u Pelhřimova"}, {"lat": 49.3854, "lng": 15.3286, "label": "Čermákovy louky"}, {"lat": 49.58306, "lng": 15.93722, "label": "Žďár nad Sázavou"}, {"lat": 49.67079, "lng": 16.03238, "label": "Skalní útvar Devět skal"}, {"lat": 49.66056, "lng": 16.07222, "label": "Skalní útvar Drátník"}, {"lat": 49.68606, "lng": 16.09333, "label": "Skály Čtyři palice"}, {"lat": 49.64608, "lng": 16.12108, "label": "Restaurace: Hotel Sněžné – Restaurace (Sněžné)"}, {"lat": 49.55497, "lng": 16.27954, "label": "Rozhledna Karasín"}, {"lat": 49.4563, "lng": 15.8653, "label": "Baba – V Bukách"}, {"lat": 49.4131, "lng": 15.535, "label": "Zaječí skok"}, {"lat": 49.3464, "lng": 15.2119, "label": "Cíl – Mezná u Pelhřimova"}]'::jsonb, mapy_url = 'https://www.google.com/maps/dir/?api=1&origin=49.3464,15.2119&destination=49.3464,15.2119&travelmode=driving&waypoints=49.3854,15.3286%7C49.58306,15.93722%7C49.67079,16.03238%7C49.66056,16.07222%7C49.68606,16.09333%7C49.64608,16.12108%7C49.55497,16.27954%7C49.4563,15.8653%7C49.4131,15.535', geometry = null, updated_at = now() where id = v_route;
end $$;

-- ── Překlady nových bodů: přeplánuj cron backfill (viz 20260704_route_translations_cron.sql)
do $$
begin
  begin
    perform cron.unschedule('backfill-route-translations');
  exception when others then null;
  end;
  perform cron.schedule(
    'backfill-route-translations',
    '* * * * *',
    $cron$ select public.trigger_route_translation_backfill(); $cron$
  );
exception when others then
  raise warning 'cron.schedule selhalo (pg_cron nedostupné?): %', sqlerrm;
end $$;

commit;
